import{_ as r,o as e,c as a,a3 as o}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"水管传输规则研究","description":"","frontmatter":{"translationSource":{"title":"水管传输规则研究","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=xnJEea1kQCy2zZf8T8Z62O","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-pipe-transport-rules"}]]},"headers":[],"relativePath":"zh/research-on-pipe-transport-rules.md","filePath":"zh/page-xnJEea1kQCy2zZf8T8Z62O.md"}'),c={name:"zh/research-on-pipe-transport-rules.md"};function i(t,p,s,n,l,h){return e(),a("div",null,[...p[0]||(p[0]=[o('<div class="logistics-content"><h1 id="水管传输规则研究" tabindex="-1">水管传输规则研究 <a class="header-anchor" href="#水管传输规则研究" aria-label="Permalink to &quot;水管传输规则研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>xnJEea1kQCy2zZf8T8Z62O</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=xnJEea1kQCy2zZf8T8Z62O" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-pict7gf1bLlBlqhNrk4Yl9"></span></p><h4 id="传输规则" tabindex="-1">传输规则 <a class="header-anchor" href="#传输规则" aria-label="Permalink to &quot;传输规则&quot;">​</a></h4><p>目前认为传输规则符合</p><p>相当于四倍速的传送带，移动为每秒分别移动两次，渲染与操作被对齐到以秒为单位或从服务器下载数据与上传数据至服务器以秒对齐。同一根水管中不会同时进入两种液体，此时被视为阻塞。</p><p>分流器迟滞输出现象在水管中也可以看到，这一点记录到<a href="/endfield-skydoc/zh/output-lag-observations-and-mechanism-investigation">迟滞输出现象(4n物品卡半格)整理与原理探究</a>中</p><p>关于存在高低差的水管现象研究暂未进行</p><p><span id="source-block-8hw0roUIrVQvGR8LNYpDwH"></span></p><h4 id="液滴损失现象" tabindex="-1">液滴损失现象 <a class="header-anchor" href="#液滴损失现象" aria-label="Permalink to &quot;液滴损失现象&quot;">​</a></h4><p>据报告，在某些情况下存在液体在循环体系中逐渐减少的现象。目前未检出除了水泵给水循环以外的损失现象</p><p><span id="source-block-ywK4aInuL3po5u1vseysjl"></span></p><h4 id="渲染规则" tabindex="-1">渲染规则 <a class="header-anchor" href="#渲染规则" aria-label="Permalink to &quot;渲染规则&quot;">​</a></h4><p>渲染会保持两秒，在第一秒内流入的液体不改变渲染流体内容，在第二秒内流入的液体会修改渲染流体内容，逆转流向会立刻重置渲染</p><p><span id="source-block-JzIMUqaxmK2Qe0ikIis4OA"></span></p><h4 id="暗管bug与特性" tabindex="-1">暗管bug与特性 <a class="header-anchor" href="#暗管bug与特性" aria-label="Permalink to &quot;暗管bug与特性&quot;">​</a></h4><p>目击到双入口暗管同时进入的液滴不会同时输出的bug</p><p>当2/s液滴进入单口暗管时疑似会堆积</p><p><span id="source-block-1tHPXsSlVEW7krAJi0zuoB"></span></p><h4 id="异常的降速现象" tabindex="-1">异常的降速现象 <a class="header-anchor" href="#异常的降速现象" aria-label="Permalink to &quot;异常的降速现象&quot;">​</a></h4><p>据报告，在水管较短情况下会出现水管无法跑满速的现象</p><details><summary>聊天记录</summary><p>c  0:39:32</p><p>(<em>^▽^</em>)<br> 每单位管线的流体储量是1，如果过短，会导致，水管有时候不满速</p><p>@(<em>^▽^</em>) ?真的假的</p><p>Orirock  0:40:13</p><p>一直都有这个问题</p><p>c  0:40:33</p><p>？</p><p>c  0:40:53</p><p>但是你机器里进的水还是一样的啊</p><p>Orirock  0:41:15</p><p>过短管道跑不了满速</p><p>c  0:41:31</p><p>不是为啥 我不理解</p><p>c  0:41:36</p><p>我真第一次知道</p><p>c  0:41:47</p><p>有啥研究吗</p><p>Orirock  0:42:17</p><p>这应该属于bug</p><p>c  0:42:53</p><p>有没有研究视频</p><p>c  0:43:10</p><p>emm石锤的视频</p><p>Orirock  0:44:31</p><p>挺好复现的，我也是因为产线因为这个卡过发现的（</p><p>c  0:45:45</p><p>【【終末地】水管長度影響分流】</p><p><a href="https://www.bilibili.com/video/BV1FJ546LEg1/?share_source=copy_web&amp;vd_source=d27eb273314c269c7c5618c1541df911" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1FJ546LEg1/?share_source=copy_web&amp;vd_source=d27eb273314c269c7c5618c1541df911</a></p><p>c  0:45:48</p><p>这个吗</p><p>c  0:47:53</p><p>那意思是所有管道都要尽量避免一格？</p><p>c  0:48:19</p><p>那就很恶心啊 你放个物流器不是一格吗</p><p>Orirock  0:48:27</p><p>只有满速的要考虑</p><p>Orirock  0:48:46</p><p>其实满速的短管道还是比较少的</p><p>Orirock  0:49:11</p><p>另外可能不止是一格的会有问题</p><p>Orirock  0:49:16</p><p>具体的没测试过</p><p>Orirock  0:50:41</p><p>c  0:52:12</p><p>古早视频</p><p>c  0:52:18</p><p>会不会是以前的问题</p><p>c  0:52:27</p><p>以前污水就有波动</p><p>c  0:52:35</p><p>emm不过当时又说管道没降速</p><p>Orirock  0:52:36</p><p>跟分流器应该是没什么关系</p><p>Orirock  0:52:46</p><p>就是过短管道跑不了满速</p><p>Orirock  0:52:56</p><p>c<br> 会不会是以前的问题</p><p>@c 我搓玉葫芦的时候就遇到了</p><p>Orirock  0:53:03</p><p>当时做混提纯机</p><p>Orirock  0:53:26</p><p>混两个1/2的提纯机要求必须入满速</p><p>Orirock  0:53:34</p><p>最开始做出来老是卡</p><p>Orirock  0:53:45</p><p>把有问题的那段延长就好了</p><p>Orirock  0:55:06</p><p>这一段</p><p>Orirock  0:55:46</p><p>原本就三格长，会卡</p><p>Orirock  0:56:23</p><p>混提纯机对是不是满速特别敏感</p><p>c  0:56:46</p><p>那这也太恶心了</p><p>c  0:56:55</p><p>你还得一个个测是不是满速</p><p>c  0:58:13</p><p>我说废水处理机才是对满不满速最敏感的（</p><p>c  0:59:37</p><p>c  0:59:38</p><p>有说法吗</p><p>Orirock  0:59:38</p><p>那个降速一点可能只是掉一点点铜，混提纯机降速一帧就直接卡死</p><p>Orirock  1:00:39</p><p>Orirock<br> 那个降速一点可能只是掉一点点铜，混提纯机降速一帧就直接卡死</p><p>因为要求两种液体都能满速进入，才能交替生产</p><p>Orirock  1:00:57</p><p>来晚了就让另一种液体先进去了</p><p>苍孤狼  1:03:34</p><p>Orirock<br> 哔哩哔哩</p><p>@Orirock 按理说，汇流管道会轮询</p><p>苍孤狼  1:03:51</p><p>后接的两个储水罐不该积水</p><p>c  1:04:26</p><p>所以评论区就在说他第一个连的暗管有问题</p><p>c  1:05:16</p><p>Orirock  1:05:47</p><p>Orirock</p><p>那我这里只是两个管道桥都会降速是什么原因</p><p>苍孤狼  1:06:36</p><p>4n卡1问题</p><p>苍孤狼  1:06:39</p><p>吗</p><p>Orirock  1:06:50</p><p>延长后就不降速了</p><p>c  1:07:03</p><p>原本怎么接的</p><p>Orirock  1:08:23</p><p>c  1:10:33</p><p>嘶</p><p>c  1:10:38</p><p>你群又有新课题了</p><p>c  1:12:18</p><p>会不会是相位问题</p><p>Orirock  1:12:30</p><p>好像能解释</p><p>Orirock  1:12:38</p><p>物流元件有滞后性</p><p>c  1:12:46</p><p>？</p><p>Orirock  1:13:01</p><p>它不是管道一有位置液体就能进去</p><p>Orirock  1:13:31</p><p>再加上液体要走完整个管道长度才能到这段管道的出口</p><p>Orirock  1:13:52</p><p>导致后面的岀液有间隔</p></details><p>认为应该是由迟滞输出现象类似原因导致的，移交至迟滞输出相关研究</p><p><span id="source-block-hWOMdL8nF6l1crvBg94X9L"></span></p><h4 id="分流器接限速器异常分流" tabindex="-1">分流器接限速器异常分流 <a class="header-anchor" href="#分流器接限速器异常分流" aria-label="Permalink to &quot;分流器接限速器异常分流&quot;">​</a></h4><p>据报告，分流器紧贴限速准入口可能不能跑满准入口的限速。</p><p>经查验，给如如下例子，假定输入连续5s的2滴/s，再输入连续5s的0/s，显然前5s可以跑满限速，后5s却无法跑满限速，平均下来就是低于限速的流量，需要在限速前添加缓冲实现。本质是缓冲不足以支持理想系统逻辑。</p><p><span id="source-block-hrkeHPvDHjYrB6xAUzEgpE"></span></p><h4 id="一些特殊的工厂接受逻辑" tabindex="-1">一些特殊的工厂接受逻辑 <a class="header-anchor" href="#一些特殊的工厂接受逻辑" aria-label="Permalink to &quot;一些特殊的工厂接受逻辑&quot;">​</a></h4><p>对于管道输入</p><p>只接受气体：储气罐</p><p>只接受液体：储液罐、反应池</p><p>只接受激活物：固气机、液气机的激活物口</p><p>只接受同种液体：暗管、储气罐、储液罐、管道、准入口</p></div>',1)])])}const u=r(c,[["render",i]]);export{k as __pageData,u as default};
